=== grok-leg ===
// VER-11 grok ACP leg driver — spawns `grok agent stdio` (ACP/JSON-RPC),
// runs initialize → session/new → session/prompt, collects session/update
// frames until end_turn. Every frame is logged for evidence; tool calls and
// agent text are extracted as receipts. Optional resume: pass --resume-session
// <sessionId> to reopen the same session and send another prompt.
import { spawn } from 'node:child_process'
import { createWriteStream, readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'

const ROOT = '/tmp/mahas-ver-11'
const GROK = '/home/pyosechang/.local/bin/grok'

// ---- args: --member lead|worker --prompt <file|text> [--resume-session <id>] [--out <name>]
const args = process.argv.slice(2)
const opt = (k) => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : null }
const member = opt('--member') ?? 'lead'
const promptArg = opt('--prompt') ?? ''
const resumeSession = opt('--resume-session')
const outName = opt('--out') ?? `grok-${member}-${Date.now()}`

const CHECKOUT = `${ROOT}/exec/${member}`
const MANDATORY = readFileSync(`${ROOT}/out/mandatory-${member}.md`, 'utf8')
const promptText = promptArg.startsWith('/') ? readFileSync(resolve(promptArg), 'utf8') : promptArg

const env = {
  ...process.env,
  MAHAS_CONFIG_DIR: `${ROOT}/config`,
  MAHAS_ROLE: 'worker',
  MAHAS_CONNECTION_FILE: `${CHECKOUT}/worker-connection.json`,
  MAHAS_CLI: 'mahas',
  PATH: `${ROOT}/bin-${member}:${process.env.PATH}`
}

const logPath = `${ROOT}/out/${outName}.frames.jsonl`
const log = createWriteStream(logPath)
const frames = []

const child = spawn(GROK, [
  '--always-approve',
  '--system-prompt-override', MANDATORY,
  'agent', 'stdio'
], { env, cwd: CHECKOUT, stdio: ['pipe', 'pipe', 'pipe'] })

child.stderr.on('data', (d) => log.write(JSON.stringify({ t: 'stderr', data: String(d) }) + '\n'))

let buf = ''
const pending = new Map()
let seq = 0
const updates = []
let sessionId = null
let endTurn = null

child.stdout.on('data', (d) => {
  buf += d
  let i
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1)
    if (!line.trim()) continue
    let msg
    try { msg = JSON.parse(line) } catch { continue }
    log.write(JSON.stringify({ t: 'in', msg }) + '\n')
    frames.push(msg)
    if (msg.method === 'session/update') {
      updates.push(msg.params?.update)
      const u = msg.params?.update
      if (u?.sessionUpdate === 'end_turn' || u?.stopReason) endTurn = u
    }
    if (msg.id !== undefined && pending.has(msg.id)) {
      pending.get(msg.id)(msg); pending.delete(msg.id)
    }
  }
})

function send(method, params, isNotif = false) {
  const msg = isNotif
    ? { jsonrpc: '2.0', method, params }
    : { jsonrpc: '2.0', id: ++seq, method, params }
  log.write(JSON.stringify({ t: 'out', msg }) + '\n')
  child.stdin.write(JSON.stringify(msg) + '\n')
  if (isNotif) return Promise.resolve(null)
  // session/prompt resolves only when the whole turn completes — long budget
  const budget = method === 'session/prompt' ? 1500000 : 120000
  return new Promise((res, rej) => {
    pending.set(seq, res)
    setTimeout(() => rej(new Error(`timeout waiting for ${method}`)), budget)
  })
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

const init = await send('initialize', { protocolVersion: 1, clientCapabilities: { fs: { readTextFile: false, writeTextFile: false }, terminal: false } })
if (init.error) { console.error('init error', init.error); process.exit(1) }
await send('initialized', {}, true)

if (resumeSession) {
  const res = await send('session/load', { sessionId: resumeSession, cwd: CHECKOUT, mcpServers: [] })
  if (res.error) {
    const res2 = await send('session/resume', { sessionId: resumeSession, cwd: CHECKOUT })
    if (res2.error) { console.error('resume error', res2.error); process.exit(1) }
    sessionId = resumeSession
    console.log('resumed via session/resume', sessionId)
  } else {
    sessionId = resumeSession
    console.log('resumed via session/load', sessionId)
  }
} else {
  const sess = await send('session/new', { cwd: CHECKOUT, mcpServers: [] })
  if (sess.error) { console.error('session/new error', sess.error); process.exit(1) }
  sessionId = sess.result.sessionId
  console.log('session', sessionId)
}

const promptRes = await send('session/prompt', {
  sessionId,
  prompt: [{ type: 'text', text: promptText }]
})
if (promptRes.error) { console.error('prompt error', promptRes.error); process.exit(1) }

// prompt result carries stopReason — that IS the turn completion signal;
// session/update end_turn is a secondary/optional notification.
if (!endTurn && promptRes.result?.stopReason) endTurn = { stopReason: promptRes.result.stopReason }

// collect any trailing session/update frames (with a hard ceiling)
const deadline = Date.now() + 15000
while (!endTurn && Date.now() < deadline) await sleep(250)
await sleep(1500) // drain trailing notifications

const agentText = updates
  .filter((u) => u?.sessionUpdate === 'agent_message_chunk')
  .map((u) => u.content?.text ?? '')
  .join('')
const toolCalls = updates.filter((u) => u?.sessionUpdate === 'tool_call' || u?.sessionUpdate === 'tool_call_update')

const result = {
  member, sessionId, outName,
  promptResult: promptRes.result ?? null,
  endTurn,
  agentText,
  toolCallCount: toolCalls.length,
  toolCalls: toolCalls.map((t) => ({ title: t?.title ?? t?.toolCallId, status: t?.status, kind: t?.kind })).slice(0, 50),
  frameCount: frames.length,
  logPath
}
writeFileSync(`${ROOT}/out/${outName}.result.json`, JSON.stringify(result, null, 2))
console.log(JSON.stringify({ sessionId, endTurn, agentText: agentText.slice(0, 600), toolCalls: toolCalls.length }, null, 2))
child.kill('SIGTERM')
setTimeout(() => { try { child.kill('SIGKILL') } catch {} process.exit(0) }, 1500)
